/* Scene albums and dialogue CG use existing SFW studio routes. */
(() => {
 const el=id=>document.getElementById(id);let page=0,pages=1,key='',working=false,loaded=false;
 const note=(text,error=false)=>{el('cg-album-status').textContent=text;el('cg-album-status').classList.toggle('error',error);};
 async function api(params){const r=await fetch('/api/art',{method:'POST',headers:{'X-Play-Token':token,'Content-Type':'application/json'},body:JSON.stringify({operation:'atelier',params})});const data=await r.json();if(!r.ok)throw Error(data.message||'CG 圖集無法讀取。');return data;}
 async function album(){if(working)return;working=true;try{const data=await api({command:'cg_gallery',scene:el('cg-album-scene').value,page});const g=data.gallery;page=g.page;pages=g.pages;const box=el('cg-album-items');box.replaceChildren();for(const j of g.items){const f=document.createElement('figure'),caption=document.createElement('figcaption');caption.textContent=(state.roster.find(x=>x.id===j.actor)?.name||state.player.name)+' · '+j.place_name+' · '+(window.LifeI18n?.t(j.status)||j.status);f.append(caption);if(j.status==='ready'&&j.url){const image=document.createElement('img');image.src=j.url;image.alt='場景 CG';image.loading='lazy';const b=document.createElement('button');b.textContent='顯示這張 CG';b.onclick=async()=>{try{await api({command:'cg_select',id:j.job_id});await send('ui_hold',{},true);note('已選用場景 CG。');}catch(e){note(e.message,true);}};f.append(image,b);}box.append(f);}el('cg-album-page').textContent=`${page+1} / ${pages} · ${g.total}`;el('cg-album-prev').disabled=page===0;el('cg-album-next').disabled=page>=pages-1;if(!g.items.length)note('這個場景尚無 CG；可手動生成或等待新對話。');else note('同一場景的舊 CG 會保留。');}catch(e){note(e.message,true);}finally{working=false;}}
 function open(){const t=state.cg.timeline;if(!t)return;loaded=true;el('cg-dialogue-enabled').checked=t.enabled;el('cg-dialogue-interval').value=t.interval;el('cg-auto-show').checked=t.auto_show;const s=el('cg-album-scene');s.replaceChildren();const all=document.createElement('option');all.value='';all.textContent='全部場景';s.append(all);for(const [id,name] of Object.entries(state.location_names).filter(([id])=>!id.startsWith('room-'))){const o=document.createElement('option');o.value=id;o.textContent=name;s.append(o);}s.value=t.scene;page=0;key='';album();}
 el('illustration-open').addEventListener('click',open);el('cg-album-scene').onchange=()=>{page=0;album();};el('cg-album-refresh').onclick=()=>album();el('cg-album-prev').onclick=()=>{page=Math.max(0,page-1);album();};el('cg-album-next').onclick=()=>{page=Math.min(pages-1,page+1);album();};
 el('cg-dialogue-save').onclick=async()=>{try{await api({command:'cg_timeline_config',enabled:el('cg-dialogue-enabled').checked,interval:Number(el('cg-dialogue-interval').value),auto_show:el('cg-auto-show').checked});await send('ui_hold',{},true);note('對話 CG 設定已保存；只處理之後的新對話。');}catch(e){note(e.message,true);}};
 const original=window.renderLife;window.renderLife=()=>{original?.();if(!loaded||!el('illustration-modal').open||!state.cg.timeline)return;const t=state.cg.timeline,signature=JSON.stringify([t.scene,t.count,t.active?.job_id,state.cg.jobs.map(j=>[j.job_id,j.status])]);if(signature!==key){key=signature;if(el('cg-album-scene').value&&el('cg-album-scene').value!==t.scene&&t.auto_show){el('cg-album-scene').value=t.scene;page=0;}album();}if(t.error)note(t.error,true);};
})();
